INSERT INTO `products` VALUES (5687,_binary '','Dynamic Island, A16 Bionic, 48MP main camera. The everyday icon, reimagined.','https://images.unsplash.com/photo-1592750475338-74b7b21085ab?w=1200&q=80&auto=format&fit=crop','iPhone 15 (128GB)',69900.00,4.7,1284,23,1),(5688,_binary '','Galaxy AI, 200MP camera, titanium frame. Built for the next decade.','https://images.unsplash.com/photo-1553062407-98eeb64c6a62?w=1200&q=80&auto=format&fit=crop','Samsung Galaxy S24 Ultra',124999.00,4.6,642,23,1),(5689,_binary '','Snapdragon 8 Gen 3, 100W charging, ProXDR display.','https://images.unsplash.com/photo-1511707171634-5f897ff02aa9?w=1200&q=80&auto=format&fit=crop','OnePlus 12R',39999.00,4.5,510,23,1),(5690,_binary '','200MP camera, 120Hz AMOLED, value flagship killer.','https://images.unsplash.com/photo-1592750475338-74b7b21085ab?w=1200&q=80&auto=format&fit=crop','Redmi Note 13 Pro',22999.00,4.3,2310,23,1),(5691,_binary '','M2 chip, 18-hour battery, silent fanless design. Featherlight.','https://images.unsplash.com/photo-1517336714731-489689fd1ca8?w=1200&q=80&auto=format&fit=crop','MacBook Air M2',99900.00,4.8,890,24,1),(5692,_binary '','Intel Core i5, 16GB RAM, 512GB SSD. Workhorse for everyday.','https://images.unsplash.com/photo-1496181133206-80ce9b88a853?w=1200&q=80&auto=format&fit=crop','Lenovo IdeaPad Slim 3',42990.00,4.2,412,24,1),(5693,_binary '','RTX 4070, 240Hz, RGB keyboard. Built for the arena.','https://images.unsplash.com/photo-1496181133206-80ce9b88a853?w=1200&q=80&auto=format&fit=crop','ASUS ROG Strix G16',149990.00,4.6,188,24,1),(5694,_binary '','Industry-leading noise cancellation. Silence, refined.','https://images.unsplash.com/photo-1505740420928-5e560c06d30e?w=1200&q=80&auto=format&fit=crop','Sony WH-1000XM5',29990.00,4.8,1540,25,1),(5695,_binary '','42-hour playback, ENx tech. Sound for the streets.','https://images.unsplash.com/photo-1606220588913-b3aacb4d2f46?w=1200&q=80&auto=format&fit=crop','boAt Airdopes 141',1299.00,4.1,8800,25,1),(5696,_binary '','Waterproof, bold bass, 12 hours of play. Take it anywhere.','https://images.unsplash.com/photo-1487215078519-e21cc028cb29?w=1200&q=80&auto=format&fit=crop','JBL Flip 6 Speaker',7999.00,4.6,2100,25,1),(5697,_binary '','Double-tap gesture, S9 chip, brightest Apple display yet.','https://images.unsplash.com/photo-1546868871-7041f2a55e12?w=1200&q=80&auto=format&fit=crop','Apple Watch Series 9',41900.00,4.7,690,26,1),(5698,_binary '','1.85 AMOLED, BT calling, 7-day battery. Smart, accessible.','https://images.unsplash.com/photo-1523275335684-37898b6baf30?w=1200&q=80&auto=format&fit=crop','Noise ColorFit Pro 5',3499.00,4,3200,26,1),(5699,_binary '','Fast, safe, compact. The essential power companion.','https://images.unsplash.com/photo-1590658268037-6bf12165a8df?w=1200&q=80&auto=format&fit=crop','Apple USB-C Charger 20W',1900.00,4.5,4100,27,1),(5700,_binary '','Quiet clicks, 8K DPI, multi-device flow. The pro\'s pointer.','https://images.unsplash.com/photo-1527864550417-7fd91fc51a46?w=1200&q=80&auto=format&fit=crop','Logitech MX Master 3S',8999.00,4.8,920,27,1),(5701,_binary '','240gsm combed cotton, relaxed fit. A wardrobe foundation.','https://images.unsplash.com/photo-1521572163474-6864f9cf17ab?w=1200&q=80&auto=format&fit=crop','Premium Cotton Tee — Obsidian',899.00,4.4,1200,28,1),(5702,_binary '','Japanese selvedge, raw denim. Ages beautifully with you.','https://images.unsplash.com/photo-1542272604-787c3835535d?w=1200&q=80&auto=format&fit=crop','Selvedge Denim Jeans — Indigo',2999.00,4.5,640,28,1),(5703,_binary '','Tailored silhouette, structured shoulders. Winter authority.','https://images.unsplash.com/photo-1591047139829-d91aecb6caea?w=1200&q=80&auto=format&fit=crop','Wool-blend Overcoat — Charcoal',6999.00,4.6,210,28,1),(5704,_binary '','Energy-return foam, breathable knit. Mile after mile.','https://images.unsplash.com/photo-1542291026-7eec264c27ff?w=1200&q=80&auto=format&fit=crop','Runner Pro Sneakers — White',4499.00,4.5,880,29,1),(5705,_binary '','Full-grain leather, Goodyear-welted. Built to last decades.','https://images.unsplash.com/photo-1605812860427-4024433a70fd?w=1200&q=80&auto=format&fit=crop','Leather Chelsea Boots — Tan',8999.00,4.7,320,29,1),(5706,_binary '','Enamelled, oven-to-table. Heirloom cookware for slow food.','https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=1200&q=80&auto=format&fit=crop','Cast Iron Dutch Oven 5L',3499.00,4.6,540,30,1),(5707,_binary '','Ultrasonic mist, 7-colour ambient light. Set the atmosphere.','https://images.unsplash.com/photo-1507473885765-e6ed057f782c?w=1200&q=80&auto=format&fit=crop','Aroma Diffuser & Mood Lamp',1799.00,4.3,980,30,1),(5708,_binary '','Tri-ply, induction-ready. The complete kitchen arsenal.','https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=1200&q=80&auto=format&fit=crop','Stainless Steel Cookware Set (7)',8999.00,4.5,360,30,1),(5709,_binary '','10% vitamin C, hyaluronic. Glow that shows in a week.','https://images.unsplash.com/photo-1556228720-195a672e8a03?w=1200&q=80&auto=format&fit=crop','Vitamin C Brightening Serum',749.00,4.2,4100,31,1),(5710,_binary '','Ceramide + niacinamide. 48-hour hydration, no greasy feel.','https://images.unsplash.com/photo-1556228720-195a672e8a03?w=1200&q=80&auto=format&fit=crop','Hydra-Glow Moisturizer',599.00,4.3,2600,31,1),(5711,_binary '','6 nude shades, transfer-proof. All-day wear, zero compromise.','https://images.unsplash.com/photo-1556228720-195a672e8a03?w=1200&q=80&auto=format&fit=crop','Matte Liquid Lipstick Set',899.00,4.1,1900,31,1),(5712,_binary '','Museum-grade giclée, oak frame. Van Gogh, immortalized.','https://images.unsplash.com/photo-1546435770-a3e426bf472b?w=1200&q=80&auto=format&fit=crop','Starry Night — Framed Print',4999.00,4.9,420,32,1),(5713,_binary '','Hand-stretched, original composition. A statement wall.','https://images.unsplash.com/photo-1546435770-a3e426bf472b?w=1200&q=80&auto=format&fit=crop','Abstract Indigo Canvas 36\"',8999.00,4.8,160,32,1),(5714,_binary '','Warm dimmable glow, solid brass. Light as sculpture.','https://images.unsplash.com/photo-1507473885765-e6ed057f782c?w=1200&q=80&auto=format&fit=crop','Brass Sculptural Table Lamp',6499.00,4.7,240,32,1),(5715,_binary '','Matte glaze, sculptural form. Quiet elegance for any shelf.','https://images.unsplash.com/photo-1546435770-a3e426bf472b?w=1200&q=80&auto=format&fit=crop','Minimalist Ceramic Vase',1299.00,4.6,510,32,1),(5716,_binary '','24-bit hi-fi audio, intelligent ANC. Pocket-sized concert.','https://images.unsplash.com/photo-1590658268037-6bf12165a8df?w=1200&q=80&auto=format&fit=crop','Galaxy Buds2 Pro',17999.00,4.5,720,25,1),(5717,_binary '','WARNING: Please IDENTIFY MODEL NUMBER on the bottom of your Macbook. Only fits for model A2338/ A2289/ A2251 (Macbook Pro 13 w/ Touch Bar, 2022/2020 release). Extra Care Yet Not Bulky. Our skin is capable of protecting the surface of your Macbook from daily scratches, dust, oil, water and fingerprint. Your Macbook remains fresh some years later. Elegant Style. Our stylish design and printing tech give your Macbook a 360 degree decorative and impressive looking. Take it out and get tons of compliments. Easy Apply. Easy, bubble-free installation and goo-free removal. Installation guide is well documented in paper material and video format. 100% SATISFACTION GUARANTEED. We use best vinyl material and printing technology and offer premium service. Full refund is guaranteed if you are not satisfied with our product.','https://m.media-amazon.com/images/I/61RPxmi+mPL._AC_SL1500_.jpg','Digi-Tatoo Decal Skin Compatible With MacBook Pro 13 inch (Model A2338/ A2289/ A2251) - Protective and Decorative Full Body Laptop Skin Decal Sticker, Anti-Scratch Vinly Skin Sticker Wrap [Fresh Marble]',25000.00,4.5,246,24,1),(5718,_binary '','☛NotoCity 22mm band is designed for Vivoactive 4 / Samsung Gear S3 Classic / S3 Frontier / Gear Live / Samsung Galaxy Watch 46mm / Huawei Watch GT / Tickwatch Pro / S2 / E2 / Pebble Classic / Time / Time Steel / Pebble 2 (Not Pebble steel) / Other Watches with 22mm lugs. ➹Wrist Size: Small size fits wrist: 6.49inches-8.46inches (165-215mm), Large size fits wrist: 7.28inches-9.25inches (185-235mm) ,Please measure your wrist and make sure the size before you purchase. ➹No Tool Needed: Quick Release Pin is easy to wear or remove. Bands made of high-quality soft Silicone material, Anti-sweat, soft and more comfortable to wear. Metal clasp locks onto your watch band interface precisely and securely, so it\'s not moving on the watch band. ➹Suitable for Many Occasions: Good for perspiration which is suitable for sports of various kinds. Such as, Running, Walking, Climbing, swimming, biking and others. Simple stripe design, suitable for daily life, study and work. ☎Any problem with the item you receive or any opinion, please don\'t hesitate to contact us, we will find the best solution to solve.','https://m.media-amazon.com/images/I/51ajKKbi76L._AC_UL1000_.jpg','NotoCity Compatible with Vivoactive 4 band 22mm Quick Release Silicone Bands/Garmin Darth Vader/First Avenger/Polar Vantage Smartwatch Sport Breathable Strap Replacement for Gear S3 Classic Watchband',839.00,4.5,233,27,1),(5719,_binary '','all Genuine High Quality Motorola Made Accessories, including Multimedia Station with HDMI technology, HDMI Cable and AC Wall Charger, Motorola Navigation / Music Vehicle Charging Mount Car Dock and Motorola 12v Vehicle Power Adapter Charger!','https://m.media-amazon.com/images/I/51-DXSMlHaL._AC_.jpg','Motorola Droid X Essentials Combo Pack',1259.00,3.8,64,30,1),(5720,_binary '','Compatibility Custom designed for your precious Garmin Vivofit 4 Activity Tracker, this Garmin Watch Sport Band features a combination of functionality and style. Fit for Garmin Vivofit 4 Activity Tracker ONLY. NOT for Garmin Vivofit 1/Garmin Vivofit 2/Garmin Vivofit 3. Feature Material: Silicone. NOTE: Replacement Bands Only! Small fits wrists with a circumference of 122-188mm.  Large fits wrists with a circumference of 148-215mm. Models for selection: For Garmin Vivofit 4 Activity Tracker Only. Contracted design style, with you life contracted and not simple. Package Included Soft Silicone Replacement Watch Band Strap for Garmin Vivofit 4 Activity Tracker (No Tracker)','https://m.media-amazon.com/images/I/61J-V53DqJL._AC_SL1000_.jpg','QGHXO Band for Garmin Vivofit 4, Soft Silicone Replacement Watch Band Strap for Garmin Vivofit 4 Activity Tracker, Small, Large, Ten Colors (5PCS Bands-Girl, Large)',1251.00,4.4,707,27,1),(5721,_binary '','Affordable and convenient way to cover your sonar unit. Protects from the sun and repells rain/snow. (It is water resistant, not waterproof). Has drawstring on bottom for securing tightly. Oversize design to fit over cables.','https://m.media-amazon.com/images/I/51VAoCIS-dL._AC_.jpg','Fishfinder, Depth Finder Poly Sun Cover for 3 - 4 Models - Protects Your Screen from Sun / Weather Damage',923.00,4.4,86,27,1),(5722,_binary '','This is a special usb stick that make as a cute camera shape.It is fun that use it to store photos and videos you tade;Or as a surprising gift for photographers. The perfect small size USB memory stick comes with a beaded key chain,you can hang it on something to decorate the thing you want,such as keychain/bag. Made out of soft rubber,shockproof, drop-proof Allow to store all of homework,course files,photos,favorite music and film. No need drive,only plug in. Easy to read and read in high speed.  Package Included: 1x U Disk 1x Chain','https://m.media-amazon.com/images/I/51+NmbjgpRL._AC_SL1000_.jpg','Novelty Cute Cartoon USB 2.0 Flash Drive Data Storage Memory Stick Cartoon USB Stick Pendrive Gift (16GB, Camera Black)',754.00,4.7,198,32,1),(5723,_binary '','ANNKE 16 channel 4K DVR security camera system can deliver true 4K Ultra HD footages day or night. IP67 waterproof housing makes the outdoor bullet surveillance cameras withstand extreme weather, perfect for outdoor & indoor protection without limitation, including home, company, office, factory, warehouse, yard, ville, garage, etc. Key Features: 4K Ultra HD Clarity 100 ft EXIR Night Vision H.265+ Video Format Expandable 5-in-1 16CH DVR 5 Smart Detection Ways Multi-Level Encryptions Area Mask for Privacy Protection Outdoor IP67 Weatherproof Digital WDR & 2D DNR 4K HDMI & 1080p VGA Output DVR Spec: Video Compression：H.264+/H.264/H.265/H.265+ Video Input: 16CH Analog HD/Analog + 16CH IP IPC Recording/Playback Resolution: Up to 8MP IP Camera Input: 16CH HDD：2 SATA Interface HDD Capacity：Up to 10 TB Capacity Network Interface: RJ45 X1 (10/100 M) USB: USB 2.0 X1, USB 3.0 X1 Camera Spec: Image Sensor: 8MP CMOS Image Sensor Video Resolution: 3840(H) × 2160(V) Lens: 2.8 mm Night Vision Distance: Up to 100ft/30m Weatherproof Rating：IP67 What’s Included? * 1× 16CH 4K DVR, NO Hard Drive * 16X 8MP Security Cameras * 1× Power Adapter for DVR * 4× Power Adapter for Cameras * 16× 60ft/18.3m BNC Cables * 4× 4-to-1 Power Splitter * 1× USB Mouse * 1× User Manual * 16× Mounting Screw Bags','https://m.media-amazon.com/images/I/71Qo4IazveL._AC_SL1500_.jpg','ANNKE 4K 16CH Security DVR Recorder with Human & Vehicle Detection and (16) 8MP Outdoor Bullet Cameras with IP67 Weatherproof, 100ft Night Vision with EXIR, Email Alert, NO Hard Drive',60000.00,5,2,30,1),(5724,_binary '','Bipra external USB 2.5 portable size hard drive comes with free carry case. You can store all data in your Pocket size drive. Ultra slim design. Formatted and ready to be used. No messing about needed, just plug it into your USB Ports and away you go. Support plug and play. Ideal for data backup, photos, video, iTunes, iPod,MP3, MP4 and presentations etc. Support USB3.0 with up to 5 GB/Sec ultrahigh transfer speed, backward compatibility usb2.0, copy huge files in a minutes time. Can be utilised on any personal computers, desktop or laptop. Formatted in NTFS for you to use on Windows OS. Available in white colour.','https://m.media-amazon.com/images/I/61W5KsZFGAL._AC_SL1500_.jpg','BIPRA U3 2.5 inch USB 3.0 NTFS Portable External Hard Drive - White (250GB)',8273.00,5,1,30,1),(5725,_binary '','Features: - Clear picture and exquisite printing. - Can easily peel off and stick on other place. - Sun protection and Waterproof! Never faded out! - Just for smooth surface. Do not suitable for rough surface. How to use: 1.Think about where you want to paste 2.Clean the surface of the object 3.Tear off the bottom paper 4.Firmly stick the sticker on the surface of the object Specification Quantity:50 pieces Size : 2-3.5 inch Material : Waterproof vinyl PVC','https://m.media-amazon.com/images/I/71teIbM9rrL._AC_SL1500_.jpg','Outer Space Planets Stickers(50Pcs),Planetary Systems Waterproof Vinyl Water Bottle Stickers for Teens Girls Adults Kids,Laptop Car Cup Computer Guitar Skateboard Luggage Phone Aesthetic Stickers Pack',25000.00,4.5,50,24,1),(5726,_binary '','Processor: Intel® Pentium® Silver N5030 Processor (1.10GHz, Up to 3.10GHz, 4M Cache) Display: 15.6” LCD IPS Display, (1920 x 1080) Operating system: Windows 10 Home 64-bit English in S mode Video Card: Intel UHD Graphics 605 Memory: 4 GB DDR4 RAM Hard drive Size: 128GB eMMC Wireless: Wi-Fi5 (802.11ac) for speeds up to 3x faster than 802.11n Ports: HDMI Output x 1, USB Type-C x 1, USB 3.0 x 2 Battery: Up to 8.5 hours of battery life Dimensions: 14.8” x 9.6” x 0.8” Inches Weight: 4.2lbs Color: Black ENERGY STAR Certified: Yes How to switch s mode to windows 10 1. On your PC running Windows 10 in S mode, open Settings > Update & Security > Activation. 2. In the Switch to Windows 10 Home or Switch to Windows 10 Pro section, select Go to the Store. (If you also see an Upgrade your edition of Windows section, be careful not to click the Go to the Store link that appears there.) 3. On the Switch out of S mode (or similar) page that appears in the Microsoft Store, select the Get button. After you see a confirmation message on the page, you\'ll be able to install apps from outside of the Microsoft Store.','https://m.media-amazon.com/images/I/61YO0u4-21L._AC_SL1500_.jpg','Gateway 15.6 FHD Ultra Slim Budget Notebook, Intel Pentium Processor(4-Core, up to 3.1 GHz), 4GB RAM, 128GB Storage, Precision Touchpad, HDMI, Type-C Windows 10S, Microsoft 365 1 Year, Charcoal Black',25000.00,4.1,15,24,1),(5727,_binary '','?VILTROX FE 24mm lens weighs in at only 12 oz (340g), it\'s compact, lightweight design enhances portability and mobility thanks to the combination of optical design utilizing two XA elements and STM AF system. It is designed for use with full-frame Sony E-mount mirrorless cameras and APS-C sensor models. ?The lens is equipped with metal electronic contacts,supports EXIF information transmission, electronic automatic iris adjustment,can record digital photo attribute information and shooting data. ?It has a high-precision STM system that ensures exceptionally fast and accurate AF performance, very minimal focus breathing not just great for video but also for focus stacking,boasts optical design comprised of 9 groups with 11 elements ,including two XA (extreme aspherical) and three ED (Extra-low Dispersion) elements. ?Build in USB port for firmware to reach a compatibility for the newest cameras model and supports EXIF information transmission ?Comes with steady, fast and smooth AUTO FOCUS,Which can capture the high speed moving objects,widely compatible with Full Frame camera A7III A7RIII A7RII A7II etc,after installing Sony camera.','https://m.media-amazon.com/images/I/71nBfBD+vPL._AC_SL1500_.jpg','VILTROX 24mm F1.8 f/1.8 FE Full-Frame Wide-Angle Prime Autofocus Lens for Sony E-Mount Camera a7R4 A7III A7S2 A5100 A6600 A6500 A6400 A6300 A6000 A7RIV A7RIII A7SIII A7III A7RII A7II A7S A7R A7',25000.00,3.9,16,32,1),(5728,_binary '','Polaroid Originals Now Viewfinder i-Type Instant Camera Polaroid’s new point-and-shoot analog instant camera has all you need to catch every life moment in an original Polaroid photograph. Now with autofocus, it’s simple to capture moments as you see them, so you can relive them forever in sharp, vivid color. Frame two moments in one with double exposure, or get yourself in the picture with self-timer and an accurate flash to make everyone look like they should. Simplicity Meets Functionality The Now takes simplicity and adds greater creative control, clean design, and vibrant color to make it more than a moment maker — but a life accessory. Thanks to the Autofocus 2 lens system, the Polaroid Now decides which lens is suitable, so you get beautiful portraits in more places, more often — even without the flash. This dreamy, artistic instant camera is ready to add some drama to your photography by providing two frames in one Polaroid photograph with the built-in double exposure. Additionally, the self-timer gives you 9 seconds to get in the picture with your friends and be a part of the memory you are capturing. Bundle Includes: Polaroid Originals Now Viewfinder i-Type Instant Camera (White) Polaroid Originals Now Viewfinder i-Type Instant Camera (White) Polaroid Originals Color Instant Film for i-Type Cameras (8 Exposures) Polaroid Originals Color Instant Film for i-Type Cameras (8 Exposures) Film Kit for Polaroid i-Type, 600 and SX-70 with Magnetic/Hanging Frames, Storage Box Film Kit for Polaroid i-Type, 600 and SX-70 with Magnetic/Hanging Frames, Storage Box Polaroid B and W Film for i-Type Cameras Polaroid B and W Film for i-Type Cameras','https://m.media-amazon.com/images/I/71CPSh8b2gL._AC_SL1500_.jpg','Polaroid Originals Now Viewfinder i-Type Instant Camera (White) Bundle with Color and B and W Instant Film and Reusable Vintage Photo Accessory (4 Items)',15119.00,4.8,48,30,1),(5729,_binary '','This pre-owned or refurbished product has been professionally inspected and tested to work and look like new. How a product becomes part of Amazon Renewed, your destination for pre-owned, refurbished products: A customer buys a new product and returns it or trades it in for a newer or different model. That product is inspected and tested to work and look like new by Amazon-qualified suppliers. Then, the product is sold as an Amazon Renewed product on Amazon. If not satisfied with the purchase, renewed products are eligible for replacement or refund under the Amazon Renewed Guarantee.','https://m.media-amazon.com/images/I/719zHGln5sL._AC_SL1500_.jpg','NVIDIA NVS 310 by PNY 1 GB DDR3 PCI Express Gen 2 x16 DisplayPort 1.2 Multi-Display Professional Graphics Board, VCNVS310DP-PB (Renewed)',2938.00,4.2,17,30,1),(5730,_binary '','Cherry powder: a quiet version of cherry red, commonly referred to as cherry powder Cherry gray: a quieter version of cherry black, usually called cherry gray','https://m.media-amazon.com/images/I/211Y0dSEIGL._AC_.jpg','luo Cherry MX RGB Switch Mute Pink Switch Mute Gray Switch Genuine German Cherry Switch (10PCS, Cherry RGB Mute Gray Switch)',1175.00,4,12,30,1),(5731,_binary '','This is a BRAND NEW Custom SHORT 4 Black Aluminum Antenna Mast. Sick of a Broken/Bent antenna or the obnoxiously tall un-stylish antenna your vehicle comes with?? Then this is the custom solution for you! This antenna is Manufactured and Anodized right here in Wisconsin!! Our experience with fit and finish is: If you want it done right, you must do it yourself! No one beats U.S.A Quality, PERIOD! This antenna is made of 6061 grade aluminum construction and finished with a durable Anodized Coating. The anodized coating cannot peel or flake off. It is part of the metal and gives the aluminum a deeper, richer metallic appearance. There will be a reduction in antenna performance due to the antenna size being shortened from the Factory antenna. Any questions or concerns on any of our products feel free to contact us by telephone or email by clicking on TheAntennaSource about us page here on Amazon. ** This antennas main design is for appearance enhancements. Its AM/FM radio reception performance works best for local stations (Satellit